var r=30;
var len=70;
var clr=215;
function setup(){
colorMode(HSB,360,100,100,100);
background(360,0,100);
//background(0);
createCanvas(594, 841);
}

function draw(){

for(let a=0;a<360;a=a+1)
{ 

var theta=a*PI/180;
stroke(0);
strokeWeight(1.5);
//noStroke();
//noFill();
// let la=map(a,0,360,0,70);
 // fill(clr,92.3-1.44*la,13.9+1.2*la);
r=r+20*cos(random(20)*a);
var x=width/2+r*cos(theta);
var y=height/2+r*sin(theta);

for(let q = 0; q < len; q+=2){
  fill(clr,92.3-1.44*q,13.9+1.2*q);

var angle = 100*noise(cos(radians(len-q)) * q);
//let angle = cos(radians(len-q)) * q;
var x2 = sin(radians(a-angle))*(q*3);
var y2 = cos(radians(a-angle))*(q*3);
ellipse(x+x2, y+y2, len-q, len-q);
}
}

}

